<script lang="ts">import {enhance} from '$app/forms'; import ImportStepper from '$lib/components/academic/ImportStepper.svelte'; let {data,form}=$props(); const headerIssues=$derived((form as {headerIssues?:Array<{code:string;message:string}>}|null)?.headerIssues??[]); let staging=$state(false); const sourceLabel=(id:string|null)=>data.setup.sources.find((s:any)=>s.id===id)?.label??'Source'; const termLabel=(id:string|null)=>{const term=data.setup.terms.find((t:any)=>t.id===id);return term?`${term.academicYear} · ${term.termName}`:'Term';}; const field='min-h-12 w-full border border-line-strong bg-white px-3 text-ink';</script>
