<section class="grid items-start gap-4 lg:grid-cols-[1.2fr_.8fr]"><form class="grid gap-4 border border-line-strong bg-white p-5" method="POST" action="?/stage" enctype="multipart/form-data" use:enhance={()=>{staging=true;return async({update})=>{staging=false;await update();};}}><div><span class="inline-grid size-12 place-items-center bg-ims-blue-ink font-mono text-xs font-bold text-white">CSV</span><p class="mt-3 font-mono text-xs uppercase tracking-[.12em] text-ims-blue-ink">New import</p><h3 class="text-xl font-semibold">Stage a class schedule</h3><p class="text-sm text-muted">UTF-8 CSV · max 2 MB · max 5,000 rows</p></div>{#if form?.stageError}<div class="border-l-4 border-danger bg-red-50 p-3 text-red-900" role="alert">{form.stageError}</div>{/if}{#if headerIssues.length}<div class="grid gap-2" aria-label="Header problems">{#each headerIssues as issue}<div class="border-l-4 border-danger bg-red-50 p-3"><strong class="block text-xs uppercase text-danger">{issue.code}</strong><span>{issue.message}</span></div>{/each}</div>{/if}
